from pysat.solvers import Glucose4
from pysat.card import CardEnc, EncType
import itertools

W = 6
G = 8
S = 4
P = G * S

def var(w, p, g):
    return w * P * G + p * G + g + 1

solver = Glucose4()

# 1. Each golfer in exactly one group per week
for w in range(W):
    for p in range(P):
        vars = [var(w, p, g) for g in range(G)]
        solver.add_clause(vars)
        for v1, v2 in itertools.combinations(vars, 2):
            solver.add_clause([-v1, -v2])

# 2. Each group has exactly S golfers per week
for w in range(W):
    for g in range(G):
        vars = [var(w, p, g) for p in range(P)]
        cnf = CardEnc.equals(lits=vars, bound=S, encoding=EncType.seqcounter, top_id=solver.nof_vars())
        for clause in cnf.clauses:
            solver.add_clause(clause)

# 3. No two golfers in the same group more than once
for p1, p2 in itertools.combinations(range(P), 2):
    # They can be in the same group at most once
    # So we cannot have (w1, g1) and (w2, g2) where they are together
    for w1, w2 in itertools.combinations(range(W), 2):
        for g1 in range(G):
            for g2 in range(G):
                solver.add_clause([-var(w1, p1, g1), -var(w1, p2, g1), -var(w2, p1, g2), -var(w2, p2, g2)])

# Symmetry breaking
# Week 0: golfer p is in group p // S
for p in range(P):
    solver.add_clause([var(0, p, p // S)])

# Golfer 0 is always in group 0
for w in range(W):
    solver.add_clause([var(w, 0, 0)])

# Week 1: golfers 0..S-1 are in different groups
for p in range(S):
    solver.add_clause([var(1, p, p)])

print("Solving...")
if solver.solve():
    print("SAT")
    model = solver.get_model()
    ans = []
    for w in range(W):
        for p in range(P):
            for g in range(G):
                if model[var(w, p, g) - 1] > 0:
                    ans.append(g)
    print(ans)
else:
    print("UNSAT")
